import { insightText } from './insight-format.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pendingOwners=new Set();
export function weightInsightMarkup(data){return data.cloud?'<section id="weight-insight" class="wi-panel" aria-label="Your weight insight"><p role="status">Opening your weight insight…</p></section>':'';}
export function mountWeightInsight({data,request}){
 const node=document.querySelector('#weight-insight');if(!node)return;
 const owner=data.viewer.id;let state,message='',working=false;
 const factText=(id,review)=>{const f=review.evidence.facts.find(f=>f.id===id);return f?new Intl.NumberFormat('en-AU',{maximumFractionDigits:2}).format(f.value)+' '+f.unit:'—';};
 const prose=(text,review)=>esc(insightText(text,review.evidence.facts,f=>new Intl.NumberFormat('en-AU',{maximumFractionDigits:2}).format(f.value)+' '+f.unit));
 function render(){if(!node.isConnected)return;const pending=pendingOwners.has(owner),consent=state?.consent?.enabled,review=state?.review,current=review&&!review.stale,needsReadings=consent===true&&state?.eligible===false;
 node.innerHTML=`<div class="wi-heading"><h2>Your weight insight</h2><span>Gemini</span></div>${current?`<h3>${prose(review.report.headline,review)}</h3><p class="wi-explanation">${prose(review.report.explanation,review)}</p><p class="wi-next">${prose(review.report.advice||'',review)}</p><details class="wi-method"><summary>See the numbers</summary><div class="wi-evidence">${review.report.supportingFactIds.map(id=>`<div><strong>${esc(factText(id,review))}</strong><span>${esc(review.evidence.facts.find(f=>f.id===id)?.label)}</span></div>`).join('')}</div><ul>${review.report.factIds.map(id=>`<li>${esc(review.evidence.facts.find(f=>f.id===id)?.label)}: ${esc(factText(id,review))}</li>`).join('')}</ul><p>Updated ${new Date(review.generatedAt).toLocaleDateString('en-AU')} · ${esc(review.model)} · high thinking</p></details>`:`<h3>${needsReadings?'Start your weight story.':consent===false?'Your trend is here. AI is your choice.':review?'Your trend is ready for a fresh look.':'What is your weight trend telling you?'}</h3><p class="wi-explanation">${needsReadings?'Your insight unlocks after four recorded days spanning two weeks.':consent===true?(review?'Update your insight for the latest pattern.':'Get a clear reading of the trend and one practical next step.'):'Let Gemini connect your readings and suggest what to do next. Names, notes and locations stay out.'}</p>`}
 <div class="wi-actions">${needsReadings?'<a class="primary-button" href="#quick-log">Log a weigh-in</a>':consent===true&&!current?`<button type="button" id="generate-weight-insight" class="primary-button" ${pending||working||!state.configured?'disabled':''}>${pending?'Reading your trend…':review?'Update my insight':'Review my trend'}</button>`:consent!==false&&consent!==true?`<button type="button" class="primary-button" id="allow-weight-ai" ${working?'disabled':''}>Allow weight analysis</button><button type="button" class="text-button" id="decline-weight-ai" ${working?'disabled':''}>Not now</button>`:''}</div>
 ${review?.stale?`<details class="wi-previous"><summary>Previous insight · ${new Date(review.generatedAt).toLocaleDateString('en-AU')}</summary><p>${prose(review.report.headline,review)}</p></details>`:''}
 ${consent===true&&!state.configured?'<p class="wi-meta">Gemini is unavailable here. Your chart is ready to explore.</p>':''}<p class="wi-status" role="status">${pending?'Comparing your readings and trend. You can keep using your journal.':''}</p><p class="wi-error" role="alert">${esc(message)}</p>
 <details class="wi-sharing"><summary>AI settings</summary><p>Weight analysis has its own sharing choice. Google’s free service may use requests to improve its products, including human review. Its terms restrict personal or sensitive submissions. <a href="https://ai.google.dev/gemini-api/terms" target="_blank" rel="noopener noreferrer">Google’s terms</a>.</p><p>Switching off stops future calls and hides saved insights. It cannot recall requests already sent.</p><button type="button" class="text-button" id="toggle-weight-ai" ${working?'disabled':''}>${consent===true?'Turn weight sharing off':'Allow weight analysis'}</button></details>`;
 node.querySelector('#generate-weight-insight')?.addEventListener('click',generate);node.querySelector('#allow-weight-ai')?.addEventListener('click',()=>preference(true));node.querySelector('#decline-weight-ai')?.addEventListener('click',()=>preference(false));node.querySelector('#toggle-weight-ai')?.addEventListener('click',()=>preference(consent!==true));}
 async function load(){try{state=await request('/api/private?route=weight-ai');render();}catch(e){if(node.isConnected)node.innerHTML=`<h2>Your weight insight</h2><p role="alert">${esc(e.message)}</p><button type="button" id="retry-weight-ai" class="text-button">Try again</button>`;node.querySelector('#retry-weight-ai')?.addEventListener('click',load);}}
 async function preference(enabled){if(working)return;working=true;message='';render();try{await request('/api/private?route=weight-ai-consent',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled})});try{localStorage.setItem('mfa-weight-ai-changed',String(Date.now()));}catch{}await load();}catch(e){message=e.message;}finally{working=false;render();}}
 async function generate(){if(pendingOwners.has(owner))return;pendingOwners.add(owner);message='';render();try{await request('/api/private?route=weight-ai',{method:'POST'});await load();}catch(e){message=e.message;}finally{pendingOwners.delete(owner);render();dispatchEvent(new CustomEvent('mfa-weight-ai-settled',{detail:owner}));}}
 const refresh=e=>{if(e.key==='mfa-weight-ai-changed'){if(node.isConnected)void load();else removeEventListener('storage',refresh);}};addEventListener('storage',refresh);
 const settled=e=>{if(!node.isConnected){removeEventListener('mfa-weight-ai-settled',settled);return;}if(e.detail===owner)void load();};addEventListener('mfa-weight-ai-settled',settled);void load();
}
